import json
from cpmpy import *

n = 13  # Number of balls
c = 3   # Number of boxes

# Decision variables: M[i][j] = 1 if ball i is in box j
M = boolvar(shape=(n, c), name='M')

constraints = []

# Each ball must be in exactly one box
for i in range(n):
    constraints.append(sum(M[i, j] for j in range(c)) == 1)

# For each x + y = z, and each box j, not all three are in the same box
for x in range(1, n+1):
    for y in range(1, n+1):
        z = x + y
        if z <= n:
            for j in range(c):
                # M[x-1][j], M[y-1][j], M[z-1][j]
                # Constraint: not all three are in the same box
                constraints.append(sum([M[x-1, j], M[y-1, j], M[z-1, j]]) <= 2)

model = Model(constraints)

if model.solve():
    # Assign each ball to the box with True value
    balls_assignment = []
    for i in range(n):
        for j in range(c):
            if M[i, j].value():
                balls_assignment.append(j+1)  # boxes labeled 1..3
                break
    solution = {'balls': balls_assignment}
    print(json.dumps(solution))
else:
    print("No solution found.")
```

